{
  "part": {
    "name": "Open-end/box-end wrench-like lever with top pocket",
    "description": "Single solid, constant-thickness (15 mm) tool-like part with an open-ended C-head on one end, a circular ring/eye with through-hole on the other, and a shallow rectangular recessed pocket on the top face along the handle.",
    "source_views": [
      "front",
      "back",
      "left",
      "right",
      "top",
      "bottom",
      "toprightiso"
    ],
    "symmetry_note": "Largely mirror-symmetric about the longitudinal center plane (X=0). Not symmetric about the mid-thickness plane (Y=7.5) due to the pocket existing only on the top face."
  },
  "Section": [
    {
      "id": "S0",
      "name": "Main plate faces (top & bottom)",
      "features included": [
        "global top planar face",
        "global bottom planar face",
        "through-hole and open-jaw outlines expressed as boundary loops on the planar faces"
      ],
      "function intent": "Provide the primary constant-thickness body surfaces for gripping/contact and define the overall silhouette boundaries.",
      "physical behavior": "Acts as the main load-carrying web in bending/torsion across the tool thickness; distributes surface contact forces and ties all sidewalls together.",
      "geometry": "Two large, parallel planar faces at Y=15 (top) and Y=0 (bottom), containing multiple boundary loops for the outer profile plus internal cutouts (ring hole, jaw slot opening, pocket opening).",
      "location": "Entire part, opposing faces along thickness direction (Y).",
